// The Constant Interface Anti-pattern: DO NOT USE!
public interface PhysicalConstants {
    // Avogadro's number (1/mol)
    static final double AVOGADROS_NUMBER   = 6.022_140_857e23;
    // Boltzmann constant (J/K)
    static final double BOLTZMANN_CONSTANT = 1.380_648_52e-23;
    // Mass of the electron (kg)
    static final double ELECTRON_MASS      = 9.109_383_56e-31;
}

// Bad: implementing the interface just to use the constants without qualification
public class ParticleCalculator implements PhysicalConstants {
    public double calculateEnergy(double temperature) {
        return 1.5 * BOLTZMANN_CONSTANT * temperature;
    }
    // PhysicalConstants constants are now part of ParticleCalculator's exported public API!
}

