public class Main {
    public static void main(String[] args) {
        // Unintended consequence: client can access constants via ParticleCalculator!
        double mass = ParticleCalculator.ELECTRON_MASS; // Leaks implementation detail!
    }
}

right_code.class:
// Clean solution: Noninstantiable utility class with static import
public final class PhysicalConstants {
    private PhysicalConstants() { throw new AssertionError(); } // Prevent instantiation

    public static final double AVOGADROS_NUMBER   = 6.022_140_857e23;
    public static final double BOLTZMANN_CONSTANT = 1.380_648_52e-23;
    public static final double ELECTRON_MASS      = 9.109_383_56e-31;
}

// Use static imports for clean, uncluttered syntax without implementing anything!
import static PhysicalConstants.*;

public class ParticleCalculator {
    public double calculateEnergy(double temperature) {
        return 1.5 * BOLTZMANN_CONSTANT * temperature; // Clean and encapsulated!
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        ParticleCalculator calc = new ParticleCalculator();
        System.out.println(calc.calculateEnergy(300.0));
    }
}
